ruleToc.chapterList:
$.data.list
@js:
//反转目录
var r=result.toArray().reverse();
//初始化列表
var list=[],
url=java.get("url"),
li=java.get("li"),
j=org.jsoup.Jsoup.parse(li),
a=j.select("a");//获取最新
for(i in r){
	name=java.getString("$.name",r[i])
	link=url+java.getString("$.id",r[i])
	list.push({text:name,href:link+".html"})
	}
	//反转添加最新
for(i=a.length-1;i>=0;i--){
	name=a[i].text()
	link=a[i].attr("href")
	list.push({text:name,href:link})
	}
list;

contentRule.content:
@js:
url="https:"+result.match(/initTxt\("([^"]+)","[^"]+"\)/)[1];
r=String(java.ajax(url).match(/_txt_call\(([\s\S]+\})\)/)[1]);
var r = eval('(' + r + ')');
				if(r.content!=null){				
      var e = r.replace;
				for (var n in e) {
					var i = new RegExp(e[n], "ig");
					r.content = r.content.replace(i, n)
				}
				result=r.content
					}else{
						result="章节加载失败，或者内容正在手打中，请稍后访问~"
						}

result;

