source.loginJs:
// 注册设备
function device_register(is_random) {
    let char, udid, model, url, data, res, header;
    if (is_random) {
        // 随机信息
        char = '0123456789ABCDEF';
        udid = "";
        for (let i = 0; i < 16; i++) {
            udid += char.charAt(Math.floor(Math.random() * char.length))
        }
        udid = udid.toLowerCase();
        char += 'GHIJKLMNOPQRSTUVWXYZ';
        model = "";
        for (let i = 0; i < 8; i++) {
            if (i == 3) {
                model += '-';
            }
            model += char.charAt(Math.floor(Math.random() * char.length));
        }
    } else {
        // 真机信息
        char = java.md5Encode(java.androidId())
        udid = char.slice(0, 16)//  + java.md5Encode(char).slice(0, 8)
        model = device
    }

    if (source.getLoginHeader() && !is_random && source.getLoginHeader().includes(device)) {
        java.toast("本设备已注册，无需重复注册")
        return false;
    }
    java.toast("开始进行设备注册: \n设备型号: " + model + "\n设备id: " + udid)
    java.log("番茄免费小说: 开始进行设备注册: \n设备型号: " + model + "\n设备id: " + udid)


    // 注册账号
    url = "https://i.snssdk.com/service/2/device_register/";
    data = JSON.stringify({
        "header": {
            "package": "com.dragon.read",
            "openudid": udid,
            "device_model": model
        }
    });
    try {
      res = post(url, TT(data));
    } catch (e) {
      java.toast("网络连接错误，请检查你的网络环境")
      throw new Error("network error")
    }
    header = "device_id=" + res.device_id + "&device_type=" + model + "&iid=" + res.install_id;

    source.putLoginHeader(header);
    java.toast("设备注册成功！");
    java.log("device_register success: " + header)
    return true;
}



// 从网页登录
function browser_login() {
    // java.removeCookie("snssdk.com")
    var cookie = java.getCookie("fanqienovel.com")
    java.log(cookie)
    if (cookie && cookie != "") {
        java.toast("请不要重复登录，请先退出登录！")
        return false
    }
    try {
        java.startBrowserAwait("https://fanqienovel.com/", "登录")
    } catch (e) {
        java.toast(e)
    }
    // java.log("snssdk cookie: " + java.getCookie("snssdk.com") + "will be reomved")
    try {
        cookie.removeCookie("snssdk.com")
    } catch (e) {}
    // java.log(cookie)
    var cookie = java.getCookie("fanqienovel.com")
    let user
    try {
      user = JSON.parse(java.ajax("https://fanqienovel.com/api/user/info/v2," + JSON.stringify({
        method: "GET",
        headers: {
          "Cookie": cookie
        }
      }))).data.name
     } catch (e) {java.log(e)}
    if (!cookie || cookie == "" || !user) {
        java.toast("未获取到登录凭据，登录失败")
        return false
    }
    java.toast("欢迎 " + user + "\n登录成功！")
    return true
}

function login() // 一定程度上加上这个函数能够支持更多的版本
{}

// 取消登录
function logout() {
    cookie.removeCookie("fanqienovel.com");
    cookie.removeCookie("snssdk.com");
    java.toast("退出登录成功");
}

function t() { java.toast("这个按钮是用来看的，别点了") }

